    # Returns list of routes (each route is a list of customer ids, excluding depot 0).

    if instance is None:
        return []
    n = int(instance.get('customer_count', 0))
    if n <= 0:
        return []
    capacity = float(instance.get('capacity', 0.0))

    # Demands extraction
    demands = list(instance.get('demands', []))
    if len(demands) != n:
        if 'demands_by_customer' in instance:
            dmap = instance['demands_by_customer']
            demands = [dmap.get(i, 0) for i in range(1, n+1)]
        else:
            demands = [1.0] * n  # fallback unit demand

    # Distance function (deterministic)
    dist_matrix = instance.get('dist', None)
    def distance(i, j):
        if dist_matrix is not None:
            try:
                return dist_matrix[i][j]
            except Exception:
                pass
        return abs(i - j)

    # Customers 1..n
    customers = list(range(1, n + 1))

    # 1) Constructive packing: sort by non-increasing demand
    customers.sort(key=lambda cid: demands[cid - 1], reverse=True)

    routes = []
    current = []
    current_cap = 0.0
    for cid in customers:
        d = demands[cid - 1]
        if d > capacity:
            # Put oversized customer in its own route (shouldn't happen in valid instances)
            if current:
                routes.append(current)
                current = []
                current_cap = 0.0
            routes.append([cid])
            continue
        if current_cap + d <= capacity:
            current.append(cid)
            current_cap += d
        else:
            if current:
                routes.append(current)
            current = [cid]
            current_cap = d
    if current:
        routes.append(current)

